    for r, c in marker:
        out[r][c] = 0

    # The marker's widest row is the crossbar; its stem selects the copy axis.
    row_counts = {}
    for r, c in marker:
        row_counts[r] = row_counts.get(r, 0) + 1
    bar = max(row_counts, key=row_counts.get)
    bar_cols = [c for r, c in marker if r == bar]
    stem_col = min(bar_cols) + (len(bar_cols) - 1) // 2
    stem_rows = [r for r, c in marker if c == stem_col and r != bar]
    above = any(r < bar for r in stem_rows)
    below = any(r > bar for r in stem_rows)

    if above and below:
        lo = min(r for r, c in obj)
        hi = max(r for r, c in obj)
        span = hi - lo + 1
        up_room, down_room = lo, h - 1 - hi
        if up_room >= span and down_room >= span:
            marker_mid = sum(r for r, c in marker) / len(marker)
            obj_mid = sum(r for r, c in obj) / len(obj)
            side = -1 if marker_mid > obj_mid else 1
        elif up_room >= span:
            side = -1
        elif down_room >= span:
            side = 1
        else:
            side = -1 if up_room > down_room else 1

        for r, c in obj:
            rr = 2 * lo - 1 - r if side < 0 else 2 * hi + 1 - r
            if 0 <= rr < h:
                out[rr][c] = 4
    else:
        lo = min(c for r, c in obj)
        hi = max(c for r, c in obj)
        span = hi - lo + 1
        left_room, right_room = lo, w - 1 - hi
        if left_room >= span and right_room >= span:
            marker_mid = sum(c for r, c in marker) / len(marker)
            obj_mid = sum(c for r, c in obj) / len(obj)
            side = -1 if marker_mid > obj_mid else 1
